bounded_host_request.command:
set -eu
for f in server/workflow.js server/adapters/ai-core.js server/role-modules/index.js; do
  if test -f "$f" && docker exec debug-ai-debug-ai-1 test -f "/app/$f"; then
    left=$(sha256sum "$f" | cut -d' ' -f1)
    right=$(docker exec debug-ai-debug-ai-1 sha256sum "/app/$f" | cut -d' ' -f1)
    if test "$left" = "$right"; then printf 'SOURCE_PARITY %s MATCH\n' "$f"; else printf 'SOURCE_PARITY %s MISMATCH\n' "$f"; fi
  else printf 'SOURCE_PARITY %s ABSENT\n' "$f"; fi
done
docker exec -i -w /app debug-ai-debug-ai-1 node - <<'NODE'
const {createAiCoreAdapter}=require("./server/adapters/ai-core.js");
const e=process.env;
const roles=["code_scout","causal_scout","researcher","local_reviewer"];
(async()=>{
  const core=createAiCoreAdapter({runtimeContextTokens:e.DEBUG_AI_CORE_CONTEXT_TOKENS,requireRuntimeContextQualification:true,dispatchMode:e.DEBUG_AI_CORE_GATE_DISPATCH_MODE,modelGateBaseUrls:{coder:e.DEBUG_AI_CORE_GATE_CODER_URL,qwen3:e.DEBUG_AI_CORE_GATE_QWEN3_URL,granite:e.DEBUG_AI_CORE_GATE_GRANITE_URL,ministral:e.DEBUG_AI_CORE_GATE_MINISTRAL_URL}});
  for(const role of roles){
    try{
      const x=await core.preflightRoleGate(role,{probeTimeoutMs:3000});
      console.log("GATE "+role+" IDENTITY_MATCH "+x.model);
    }catch(err){console.log("GATE "+role+" FAIL "+(/^[A-Z0-9_]+$/.test(err?.code||"")?err.code:"ERROR"));}
  }
  for(const route of ["status","inspect"]){
    try{
      const res=await fetch("http://127.0.0.1:8787/v1/"+route+"/run_mvrnydib_f5e96251e5",{signal:AbortSignal.timeout(4000)});
      const body=await res.json();
      const classification=res.ok?"FOUND":body?.error==="RUN_NOT_FOUND"?"RUN_NOT_FOUND":body?.error==="RUN_AUTHORITY_REQUIRED"?"RUN_AUTHORITY_REQUIRED":"OTHER";
      console.log("ARCHIVED_RUN_"+route.toUpperCase()+" "+res.status+" "+classification);
    }catch{console.log("ARCHIVED_RUN_"+route.toUpperCase()+" TRANSPORT_ERROR");}
  }
})().catch(()=>{console.log("PREFLIGHT_CONFIGURATION_FAILED");process.exitCode=1});
NODE
